input.query:
WITH ranked AS (
  SELECT Gene, "Gene name", Tissue, TRY_CAST(nTPM AS DOUBLE) AS ntpm,
         ROW_NUMBER() OVER (PARTITION BY Gene ORDER BY TRY_CAST(nTPM AS DOUBLE) DESC) AS rn
  FROM rna_tissue_consensus
)
SELECT COUNT(*) FROM ranked WHERE rn=1 AND Tissue='heart muscle';

SELECT "RNA tissue specificity", COUNT(*) FROM proteinatlas p
WHERE p.Gene IN (SELECT "Gene name" FROM rna_tissue_consensus WHERE Tissue='heart muscle' AND TRY_CAST(nTPM AS DOUBLE)>0)
GROUP BY 1;
